const app=document.getElementById('app'),title=document.getElementById('title'),$=s=>document.querySelector(s);const allowedCurrencies=['IDR','USD'];const rates={USD:1,IDR:16000};data.settings.usdToIdrRate=Number(data.settings.usdToIdrRate)||16000;data.settings.adminDisplayCurrency='IDR';function adminRate(){return Number(data.settings.usdToIdrRate)||16000}function priceValue(p,c){if(p&&p.prices&&p.prices[c]!=null&&p.prices[c]!==''&&Number(p.prices[c])>0)return Number(p.prices[c]);return (Number(p&&p.price)||0)*rates[c]}function money(n){const c=data.settings.currency||'USD';return new Intl.NumberFormat(c==='IDR'?'id-ID':'en-US',{style:'currency',currency:c,maximumFractionDigits:c==='IDR'?0:2}).format((n||0))}function orderMoney(n,o){const c=o&&o.currency||'USD';const idr=c==='USD'?Number(n||0)*adminRate():Number(n||0);return new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(idr)}function moneyCurrency(n,c){c=c||'USD';return new Intl.NumberFormat(c==='IDR'?'id-ID':'en-US',{style:'currency',currency:c,maximumFractionDigits:c==='IDR'?0:2}).format((n||0))}function displayPrice(p){return money(priceValue(p,data.settings.currency||'USD'))}function siteSettingsPayload(){return{brand:data.settings.brand||'',currency:data.settings.currency||'USD',language:data.settings.language||'EN',whatsapp:data.settings.whatsapp||'',email:data.settings.email||'',address:data.settings.address||'',catalogID:data.settings.catalogID||'',catalogIntl:data.settings.catalogIntl||'',catalogWholesale:data.settings.catalogWholesale||'',usdToIdrRate:Number(data.settings.usdToIdrRate)||16000,adminDisplayCurrency:'IDR',social:data.settings.social||{},channels:data.settings.channels||[],appearance:data.settings.appearance||{},homepage:{taglineEN:data.taglineEN||'',taglineID:data.taglineID||'',introEyebrowEN:data.introEyebrowEN||'',introEyebrowID:data.introEyebrowID||'',showIntroEyebrow:data.showIntroEyebrow!==false,hero:(data.hero||[]).map(h=>({active:h.active!==false,showEyebrow:h.showEyebrow!==false,image:h.image||'',eyebrowEN:h.eyebrowEN||'',eyebrowID:h.eyebrowID||'',titleEN:h.titleEN||'',titleID:h.titleID||'',textEN:h.textEN||'',textID:h.textID||'',eyebrowColor:h.eyebrowColor||'',titleColor:h.titleColor||'',textColor:h.textColor||'',overlayColor:h.overlayColor||'#000000',overlayOpacity:Number(h.overlayOpacity??0.28),textPosition:h.textPosition||'left',button1LabelEN:h.button1LabelEN||'',button1LabelID:h.button1LabelID||'',button1Link:h.button1Link||'#shop',button2LabelEN:h.button2LabelEN||'',button2LabelID:h.button2LabelID||'',button2Link:h.button2Link||'#catalog'})),collections:(data.collections||[]).slice(0,3).map((x,i)=>({active:x.active!==false,image:x.image||'',titleEN:x.titleEN||'',titleID:x.titleID||'',link:x.link||'#shop',number:x.number||String(i+1).padStart(2,'0'),titleColor:x.titleColor||'',overlayColor:x.overlayColor||'#000000',overlayOpacity:Number(x.overlayOpacity??0.28)})),catalogSection:{...(data.catalogSection||{}),cards:(data.catalogSection?.cards||[]).slice(0,3)},processSection:{...(data.processSection||{}),cards:(data.processSection?.cards||[]).slice(0,4)},promoSection:{...(data.promoSection||{})},journalSection:{...(data.journalSection||{}),cards:(data.journalSection?.cards||[]).slice(0,3)},storySection:{...(data.storySection||{})},wholesaleSection:{...(data.wholesaleSection||{})}}}}
async function syncSiteSettings(){return apiFetch('/api/admin/settings',{method:'PATCH',body:JSON.stringify(siteSettingsPayload())})}
function safeLocalSave(){try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch(err){console.warn('Local storage quota exceeded; production database remains source of truth.',err);return false}}function save(){safeLocalSave();syncSiteSettings().catch(err=>console.warn('Production sync failed:',err));render(active)}function logout(){sessionStorage.removeItem('palmaAdminToken');sessionStorage.removeItem('palmaAdminUser');location.href='index.html'}let active='overview';document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-tab]').forEach(x=>x.classList.remove('active'));b.classList.add('active');render(active=b.dataset.tab)});
const tabs={overview:'Ringkasan',orders:'Pesanan',products:'Produk & Stok',customers:'Pelanggan',wholesale:'Grosir / OEM',content:'Beranda & Hero',catalog:'Katalog / Flipbook',artisans:'Pengrajin & Proses',payments:'Pembayaran',invoices:'Invoice',packing:'Packing / QC',shipping:'Pengiriman',automation:'Otomatisasi',appearance:'Tampilan',media:'Media Library',channels:'Channel Penjualan',settings:'Pengaturan'};function render(t){document.getElementById('title').textContent=tabs[t]||t;({overview,orders,products,customers,wholesale,content,catalog,artisans,payments,invoices,packing,shipping,automation,appearance,media,channels,settings}[t]||overview)()}
function html(s){s=s??'';return s.replaceAll('&','&amp;').replaceAll('<','&lt;').replaceAll('>','&gt;').replaceAll('"','&quot;').replaceAll("'",'&#039;')}
function overview(){const paid=data.orders.filter(o=>['LUNAS','PAID','SETTLEMENT','SETTLED'].includes(String(o.paymentStatus||'').toUpperCase()));const rev=paid.reduce((a,o)=>a+(o.currency==='USD'?Number(o.total||0)*adminRate():Number(o.total||0)),0);document.getElementById('app').innerHTML=`<div class="stats"><div class="stat"><small>Total Pesanan</small><strong>${data.orders.length}</strong></div><div class="stat"><small>Menunggu Verifikasi</small><strong>${data.orders.filter(o=>o.paymentStatus==='Menunggu Verifikasi').length}</strong></div><div class="stat"><small>Produk</small><strong>${data.products.length}</strong></div><div class="stat"><small>Pelanggan</small><strong>${data.customers.length}</strong></div><div class="stat"><small>Pendapatan Lunas (IDR)</small><strong>${new Intl.NumberFormat('id-ID',{style:'currency',currency:'IDR',maximumFractionDigits:0}).format(rev)}</strong></div></div><div class="panel"><h2>Alur otomatis</h2><p class="sectionNote">Pembayaran terverifikasi → LUNAS → reserve stok → invoice → packing/QC → shipping → tracking → selesai.</p><div class="automation"><div class="rule"><b>PEMBAYARAN LUNAS</b><p>Order diproses, stok di-reserve, invoice dan tugas packing dibuat.</p></div><div class="rule"><b>STOK MENIPIS</b><p>Produk dengan stok di bawah minimum diberi peringatan.</p></div><div class="rule"><b>DIKIRIM</b><p>Nomor resi disimpan dan notifikasi pengiriman disiapkan.</p></div><div class="rule"><b>TERKIRIM</b><p>Order dapat ditutup dan permintaan review dijadwalkan.</p></div></div></div><div class="panel"><div class="toolbar"><h2>Pesanan terbaru</h2><button class="btn" onclick="render('orders')">Lihat semua</button></div>${orderTable(8)}</div>`}
function orderTable(limit=100,selectable=false){
  const rows=data.orders.slice(0,limit);
  return `<table class="table"><thead><tr>${selectable?'<th style="width:34px"><input id="ordersSelectAll" type="checkbox" title="Pilih semua label yang belum dicetak" onchange="toggleAllOrderLabels(this.checked)"></th>':''}<th>Order</th><th>Pelanggan</th><th>Total</th><th>Pembayaran</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${rows.map(o=>{
    const printed=!!o.labelPrintedAt;
    return `<tr>${selectable?`<td style="text-align:center">${printed?`<span class="badge" title="Label sudah pernah dicetak">SUDAH DICETAK</span>`:`<input class="order-label-select" type="checkbox" value="${html(o.productionId||o.id)}" aria-label="Pilih label ${html(o.id)}">`}</td>`:''}<td>${html(o.id)}</td><td>${html(o.customer.first)}<br>${html(o.customer.country)}</td><td>${orderMoney(o.total,o)}</td><td><span class="badge">${o.paymentStatus}</span></td><td><span class="badge">${o.orderStatus}</span></td><td><button class="btn" onclick="orderDetail('${o.id}')">Buka</button></td></tr>`;
  }).join('')||`<tr><td colspan="${selectable?7:6}">Belum ada pesanan.</td></tr>`}</tbody></table>`;
}
function toggleAllOrderLabels(checked){document.querySelectorAll('.order-label-select').forEach(el=>{el.checked=checked})}
function selectedOrderLabelRefs(){return [...document.querySelectorAll('.order-label-select:checked')].map(el=>el.value).filter(Boolean)}
async function printShippingLabels(refs){
  const list=Array.isArray(refs)?refs.filter(Boolean):[];
  if(!list.length){alert('Pilih minimal satu pesanan yang belum dicetak label.');return}
  try{
    const base=String(window.PALMA_API_BASE||'').replace(/\/+$/,'');
    const token=sessionStorage.getItem('palmaAdminToken')||'';
    const response=await fetch(base+'/api/admin/documents/labels/bulk',{method:'POST',cache:'no-store',headers:{'content-type':'application/json','authorization':'Bearer '+token},body:JSON.stringify({refs:list})});
    const ct=(response.headers.get('content-type')||'').toLowerCase();
    if(!response.ok){const raw=await response.text();let d={};try{d=JSON.parse(raw)}catch(_){}throw new Error(d.error||raw.slice(0,300)||('API HTTP '+response.status))}
    if(!ct.includes('application/pdf'))throw new Error('Server tidak mengembalikan PDF label.');
    const blob=await response.blob();
    if(blob.size<1000)throw new Error('PDF label terlalu kecil atau tidak valid.');
    const count=Number(response.headers.get('x-palma-label-count')||0);
    const skipped=Number(response.headers.get('x-palma-label-skipped')||0);
    const blobUrl=URL.createObjectURL(blob);
    await showProductionPdfUrl(blobUrl,`PALMA-ROTAN-labels-${new Date().toISOString().slice(0,10)}.pdf`);
    if(skipped)alert(`${count} label dibuat. ${skipped} pesanan dilewati karena label sudah pernah dicetak/tidak ditemukan.`);
    await loadProductionData();
  }catch(e){alert('Gagal membuat label: '+(e.message||e))}
}
async function printShippingLabel(id){return printShippingLabels([decodeURIComponent(id)])}
function orders(){document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Pesanan Pelanggan</h2><p class="sectionNote">Data pesanan dibaca langsung dari database production. Tidak ada perubahan status yang disimpan lokal sebagai sumber utama.</p></div><div style="display:flex;gap:8px;align-items:center;flex-wrap:wrap"><button class="btn" onclick="loadProductionData()">Refresh Database</button><button class="btn" onclick="printShippingLabels(selectedOrderLabelRefs())">Cetak Label Terpilih</button></div></div><div class="panelNote"><b>Cetak label serentak</b><p>Pilih beberapa pesanan yang belum dicetak. Pesanan yang sudah pernah dicetak akan otomatis dilewati.</p></div>${orderTable(100,true)}</div>`}
function orderDetail(id){const o=data.orders.find(x=>x.id===id);if(!o)return;document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><div><span class="eyebrow">ORDER CONTROL CENTER</span><h2>${html(o.id)}</h2></div><button class="btn" onclick="render('orders')">Kembali</button></div><div class="grid2"><div><h3>Pelanggan</h3><p>${html(o.customer?.first||'—')}<br>${html(o.customer?.email||o.email||'')}<br>${html(o.customer?.whatsapp||o.whatsapp||'')}<br>${html(o.customer?.address||o.address||'')}<br>${html(o.customer?.country||'')}</p><h3>Produk</h3>${(o.items||[]).map(i=>`<p>${html(i.name||i.product_name||i.id)} × ${i.qty||1} — ${orderMoney((Number(i.price)||0)*(Number(i.qty)||1),o)}</p>`).join('')||'<p>Detail item tidak dikirim oleh endpoint pesanan.</p>'}<p><b>Subtotal:</b> ${orderMoney(o.subtotal,o)}</p><p><b>Ongkir:</b> ${orderMoney(o.shipping,o)}</p><p><b>Total:</b> ${orderMoney(o.total,o)}</p></div><div><h3>Status Production</h3><p>Pembayaran: <b>${html(o.paymentStatus||'PENDING')}</b></p><p>Order: <b>${html(o.orderStatus||'NEW')}</b></p><p>Invoice: <b>${html(o.invoiceNo||'Belum dibuat')}</b></p><p>Packing: <b>${html(o.packingNo||'Belum dibuat')}</b></p><p>Label: <b>${o.labelPrintedAt?'SUDAH DICETAK':'BELUM DICETAK'}</b></p><div class="rule"><b>Dokumen production</b><p>Invoice dan packing slip diambil dari API production, bukan dibuat dari localStorage.</p><div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn" onclick="openProductionDocument('invoice','${encodeURIComponent(o.productionId||o.id)}')">Invoice</button><button class="btn" onclick="openProductionDocument('packing','${encodeURIComponent(o.productionId||o.id)}')">Packing List</button><button class="btn" onclick="printShippingLabel('${encodeURIComponent(o.productionId||o.id)}')">Cetak Label</button></div></div></div></div></div>`}
async function showProductionPdfUrl(url,filename){
  const old=document.getElementById('productionPdfModal');
  if(old){if(old.dataset.objectUrl)URL.revokeObjectURL(old.dataset.objectUrl);old.remove()}
  const modal=document.createElement('div');
  modal.id='productionPdfModal';
  modal.style.cssText='position:fixed;inset:0;z-index:99999;background:rgba(20,16,12,.82);display:flex;flex-direction:column;padding:18px';
  modal.innerHTML='<div style="display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px;color:#fff"><strong style="font-size:15px">'+html(filename)+'</strong><div style="display:flex;gap:8px"><a id="pdfDownloadBtn" class="btn" style="background:#fff;color:#211a15;text-decoration:none" href="#" download="'+html(filename)+'">Download</a><button id="pdfNewTabBtn" class="btn" style="background:#fff;color:#211a15">Tab Baru</button><button id="pdfCloseBtn" class="btn" style="background:#211a15;color:#fff">Tutup</button></div></div><div id="pdfLoading" style="flex:1;display:flex;align-items:center;justify-content:center;color:#fff;background:#fff;border-radius:8px">Memuat dokumen production…</div>';
  document.body.appendChild(modal);
  try{
    let objectUrl=url;
    if(!String(url).startsWith('blob:')){
      const r=await fetch(url,{cache:'no-store',credentials:'omit',headers:{accept:'application/pdf'}});
      const ct=(r.headers.get('content-type')||'').toLowerCase();
      if(!r.ok)throw new Error('Dokumen API HTTP '+r.status);
      if(!ct.includes('application/pdf')){
        const probe=(await r.text()).slice(0,120).replace(/\s+/g,' ');
        throw new Error('Server tidak mengembalikan PDF (Content-Type: '+(ct||'unknown')+'). Respons: '+probe);
      }
      const blob=await r.blob();
      if(blob.size<1000)throw new Error('PDF production terlalu kecil atau tidak valid ('+blob.size+' byte)');
      objectUrl=URL.createObjectURL(blob);
    }
    modal.dataset.objectUrl=objectUrl;
    modal.querySelector('#pdfDownloadBtn').href=objectUrl;
    modal.querySelector('#pdfNewTabBtn').onclick=()=>{const w=window.open(objectUrl,'_blank');if(!w)alert('Browser memblokir tab baru. Gunakan tombol Download atau izinkan popup untuk situs ini.')};
    const frame=document.createElement('iframe');
    frame.title=filename;
    frame.style.cssText='flex:1;width:100%;min-height:0;border:0;border-radius:8px;background:#fff';
    frame.src=objectUrl;
    modal.querySelector('#pdfLoading').replaceWith(frame);
  }catch(e){
    // Cross-origin PDF fetch can be blocked by a browser even when the authenticated document URL itself is valid. Fall back to the signed PDF URL instead of breaking the production document viewer.
    const frame=document.createElement('iframe');
    frame.title=filename;
    frame.style.cssText='flex:1;width:100%;min-height:0;border:0;border-radius:8px;background:#fff';
    frame.src=url;
    modal.querySelector('#pdfLoading').replaceWith(frame);
  }
  modal.querySelector('#pdfCloseBtn').onclick=()=>{if(modal.dataset.objectUrl)URL.revokeObjectURL(modal.dataset.objectUrl);modal.remove()};
}
async function openBrandedInvoice(encodedId){
  // Branded PDF uses the same authenticated production invoice endpoint.
  // Keep this as a separate button action so the existing document flow remains unchanged.
  return openProductionDocument('invoice',encodedId);
}
async function openProductionDocument(type,id){
  if(type==='label')return printShippingLabel(id);
  id=decodeURIComponent(id);
  const o=data.orders.find(x=>String(x.productionId||'')===String(id)||String(x.orderNumber||'')===String(id)||String(x.id||'')===String(id));
  const ref=o?.productionId||o?.orderNumber||id;
  const token=sessionStorage.getItem('palmaAdminToken');
  if(!token){alert('Sesi admin sudah berakhir. Silakan login kembali.');return}
  try{
    const access=await apiFetch('/api/admin/documents/access',{method:'POST',body:JSON.stringify({type,ref})});
    let documentUrl=String(access?.url||'').trim();
    if(!documentUrl){
      const base=String(window.PALMA_API_BASE||'').replace(/\/+$/,'');
      if(!base)throw new Error('PALMA_API_BASE belum dikonfigurasi');
      if(!access?.path||!access?.access_token){
        throw new Error('Tautan dokumen production tidak lengkap. Field API: '+Object.keys(access||{}).join(', '));
      }
      documentUrl=base+access.path+'?access_token='+encodeURIComponent(access.access_token);
    }
    showProductionPdfUrl(documentUrl,(type==='invoice'?'invoice-':type==='packing'?'packing-':'label-')+String(o?.orderNumber||id)+'.pdf');
  }catch(e){
    alert('Gagal membuka dokumen production: '+(e.message||e));
  }
}
function products(){document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><div><h2>Produk & Stok</h2><p class="sectionNote">Kelola harga, stok, MOQ, berat, dimensi dan foto produk.</p></div><button class="btn" onclick="newProduct()">+ Tambah Produk</button></div><table class="table"><thead><tr><th>Produk</th><th>Kategori</th><th>Harga</th><th>Stok</th><th>Tipe</th><th>MOQ</th><th>Status</th><th>Aksi</th></tr></thead><tbody>${data.products.map(p=>`<tr><td>${html(p.name)}</td><td>${p.category}</td><td>${displayPrice(p)}</td><td>${p.stock}</td><td>${p.type==='retail'?'Retail':(p.type||'custom').toUpperCase()}</td><td>${['custom','wholesale','oem'].includes((p.type||'retail').toLowerCase())?p.moq:'—'}</td><td>${p.stock<=3?'<span class="bad">Stok rendah</span>':'Aktif'}</td><td><button class="btn" onclick="editProduct('${p.id}')">Edit</button></td></tr>`).join('')||'<tr><td colspan="8">Belum ada produk.</td></tr>'}</tbody></table></div>`}
function newProduct(){const p={id:'PR'+Date.now(),name:'Produk Rotan Baru',type:'retail',category:'home',price:0,stock:0,moq:1,prices:{IDR:0,USD:0},image:'../assets/hero-collection.png',description:'',weight:1,dimensions:''};data.products.push(p);editProduct(p.id)}function editProduct(id){const p=data.products.find(x=>x.id===id);document.getElementById('app').innerHTML=`<div class="panel"><div class="toolbar"><h2>Edit Produk</h2><button class="btn" onclick="render('products')">Kembali</button></div><div class="formGrid"><label>Nama Produk<input id="pn" value="${html(p.name)}" placeholder="Contoh: Keranjang Penyimpanan Rotan"></label><select id="pt" onchange="toggleMOQ()"><option value="retail" ${(p.type||'retail')==='retail'?'selected':''}>Retail</option><option value="custom" ${p.type==='custom'?'selected':''}>Custom</option><option value="wholesale" ${p.type==='wholesale'?'selected':''}>Wholesale</option><option value="oem" ${p.type==='oem'?'selected':''}>OEM</option></select><label>Kategori<select id="pc"><option value="home" ${p.category==='home'?'selected':''}>Home Decor</option><option value="vase" ${p.category==='vase'?'selected':''}>Vase & Planter</option><option value="basket" ${p.category==='basket'?'selected':''}>Baskets</option><option value="gift" ${p.category==='gift'?'selected':''}>Gifts</option></select></label><label>Harga Dasar USD (cadangan)<input id="pp" type="number" value="${p.price}" placeholder="Contoh: 85"></label><label>🇮🇩 Harga Indonesia (IDR)<input id="pidr" type="number" min="0" value="${p.prices?.IDR??''}" placeholder="Contoh: 1360000"></label><label>🌎 Harga Internasional (USD)<input id="pusd" type="number" step="0.01" min="0" value="${p.prices?.USD??p.price??''}" placeholder="Contoh: 85"></label><input id="ps" type="number" value="${p.stock}" placeholder="Contoh: 25"><input id="pm" type="number" min="1" value="${p.moq||1}" placeholder="Contoh: 50" ${['custom','wholesale','oem'].includes((p.type||'retail').toLowerCase())?'':'disabled'}><input id="pw" type="number" step=".01" value="${p.weight||0}" placeholder="Net Weight / Unit (kg) — contoh: 1.20"><input id="pd" value="${html(p.dimensions||'')}" placeholder="Product Dimensions (cm) — contoh: 35 × 35 × 30"><input id="pmat" value="${html(p.material||'')}" placeholder="Material — e.g. Natural Rattan"><input id="phs" value="${html(p.hsCode||'')}" placeholder="HS Code — isi sesuai klasifikasi resmi"><input id="ppt" value="${html(p.packageType||'')}" placeholder="Package Type — Carton / Crate / Box"><input id="pup" type="number" min="1" value="${p.unitsPerPackage||1}" placeholder="Units per Package"><input id="ppw" type="number" min="0" step=".01" value="${p.packagingWeightKg||0}" placeholder="Packaging Weight (kg)"><label class="fullField">Deskripsi Produk<textarea id="px" placeholder="Jelaskan material, fungsi, proses, dan karakter produk">${html(p.description||'')}</textarea></label></div><div class="priceNote"><b>Harga Indonesia & Internasional</b><br>Isi harga IDR dan USD secara terpisah. Isi keduanya secara manual sesuai harga yang Anda tetapkan. Harga Indonesia dan internasional tidak harus mengikuti kurs yang sama.</div><div class="heroCard"><b>Foto Produk</b><div class="heroPreview" id="prodPreview">${p.image?`<img src="${p.image}">`:'Belum ada foto'}</div><label class="upload">📷 Pilih Foto<input type="file" accept="image/*" onchange="productImage(event,'${p.id}')"></label></div><p class="sectionNote">MOQ hanya berlaku untuk Custom / Wholesale / OEM. Produk Retail dapat dibeli mulai 1 pcs selama stok tersedia.</p><button class="btn" onclick="saveProduct('${p.id}')">Simpan Produk</button></div>`}
function toggleMOQ(){const type=$('#pt').value;$('#pm').disabled=type==='retail';if(type==='retail')$('#pm').value=1}function productImage(e,id){const f=e.target.files[0];if(!f)return;if(f.size>4*1024*1024){alert('Maksimal 4 MB');return}const r=new FileReader();r.onload=ev=>{const p=data.products.find(x=>x.id===id);p.image=ev.target.result;document.getElementById('prodPreview').innerHTML=`<img src="${p.image}">`;saveNoRender()};r.readAsDataURL(f)}async function saveProduct(id){const p=data.products.find(x=>x.id===id);Object.assign(p,{name:$('#pn').value,type:$('#pt').value,category:$('#pc').value,price:Number($('#pp').value)||0,stock:Math.max(0,Number($('#ps').value)||0),moq:['custom','wholesale','oem'].includes($('#pt').value)?Math.max(1,Number($('#pm').value)||1):1,weight:Number($('#pw').value)||0,dimensions:$('#pd').value,material:$('#pmat').value,hsCode:$('#phs').value,packageType:$('#ppt').value,unitsPerPackage:Math.max(1,Number($('#pup').value)||1),packagingWeightKg:Math.max(0,Number($('#ppw').value)||0),description:$('#px').value,prices:{IDR:$('#pidr').value===''?null:Number($('#pidr').value),USD:$('#pusd').value===''?(Number($('#pp').value)||0):Number($('#pusd').value)}});try{await apiFetch('/api/admin/products',{method:'POST',body:JSON.stringify({id:p.id,sku:p.id,type:p.type,category:p.category,stock:p.stock,moq:p.moq,weight:p.weight,dimensions:p.dimensions,material:p.material,hsCode:p.hsCode,packageType:p.packageType,unitsPerPackage:p.unitsPerPackage,packagingWeightKg:p.packagingWeightKg,image:(p.image||'').replace(/^\.\.\//,''),name:p.name,nameEN:p.name,nameID:p.name,description:p.description,descriptionEN:p.description,descriptionID:p.description,priceIDR:p.prices.IDR,priceUSD:p.prices.USD})});alert('Produk tersimpan ke database production.');await loadProductionData()}catch(err){alert('Gagal menyimpan ke production API: '+err.message);save()} }function optimizeImageFile(file,max=1400,quality=.72){return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onerror=()=>reject(new Error('File gambar tidak dapat dibaca'));reader.onload=()=>{const img=new Image();img.onerror=()=>reject(new Error('Format gambar tidak dapat diproses'));img.onload=()=>{const scale=Math.min(1,max/Math.max(img.naturalWidth,img.naturalHeight));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(img.naturalWidth*scale));canvas.height=Math.max(1,Math.round(img.naturalHeight*scale));const ctx=canvas.getContext('2d');ctx.drawImage(img,0,0,canvas.width,canvas.height);resolve(canvas.toDataURL('image/jpeg',quality))};img.src=reader.result};reader.readAsDataURL(file)})}
